// Rovara Code's REAL answers for the routes Code #1045 and #1052 serve for core tasks (and Code #1022's project-members refusal), read from code-core-task-routes.json. That file was
// generated by running Code's own handlers in clones of those PRs' trees (its `_about` says which harness made each section); a Cloud test that reads one of them fails when Cloud
// drifts from what Code really sends. Regenerate from Code's code when Code changes a shape; never edit a value to make a Cloud test pass.
import { readFileSync } from "node:fs";

type Obj = Record<string, unknown>;
/** One answer as Code's route gave it: its status and JSON body (a developer API answer without the broker's trace id, which Cloud's client drops anyway). */
export interface Answer { status: number; body: Obj }

export interface CoreTaskRoutesFixture {
  _about: string;
  /** `POST /v1/app/tasks/{taskId}/review-findings` (Code #1045 item 2) and the workflow route's refusal of the same accept on a core task. */
  page: {
    taskId: string; revision: number; candidateDigest: string; findingId: string; blockedTask: Obj;
    tokenRoute: Answer; notWebApp: Answer; noStepUp: Answer; staleStepUp: Answer; member: Answer; otherCompany: Answer; accepted: Answer; notOnCore: Answer;
  };
  /** A hosted core start writes the task's session (Code #1045 item 1); the session controls on it; a task started before that names no session. */
  sessions: {
    taskId: string; sessionId: string; startedTask: Obj; retryNothing: Answer; memberClose: Answer; otherCompanyClose: Answer; otherCompanyRetry: Answer; stop: Answer; retryAfterStop: Answer; close: Answer;
    blockedTaskId: string; blockedTask: Obj; viewerRetry: Answer; viewerClose: Answer; retry: Answer; oldTaskId: string; oldTask: Obj;
  };
  /** The old task routes, now served for a core task (Code #1045 item 3 and #1052): readers, events, comments, People. MAYA owns; TESS is shared; SAM is a member with no part; OMAR is another company's. */
  rules: {
    taskId: string; maya: string; tess: string; sam: string; omar: string;
    readersEmpty: Answer; share: Answer; readers: Answer; readerReaders: Answer; samReaders: Answer; omarReaders: Answer; readerTask: Answer; samTask: Answer;
    events: Answer; readerEvents: Answer; samEvents: Answer; omarEvents: Answer; comments: Answer; samComments: Answer; omarComments: Answer;
    people: Answer; candidates: Answer; samPeople: Answer; omarPeople: Answer; add: Answer; samTakeOwnership: Answer; omarTakeOwnership: Answer; unshare: Answer; unwiredPeople: Answer;
  };
  /** `GET .../test-environment` with the proposal's body, and `POST .../test-environment/approve` (Code #1045 item 4). */
  testenv: {
    seen: { digest: string; revision: number }; read: Answer; readOther: Answer; readNoGrant: Answer;
    approveNoStepUp: Answer; approveDeveloper: Answer; approveNoGrant: Answer; approveOtherCompany: Answer; approveStale: Answer; approved: Answer; readAfter: Answer;
  };
  /** `GET /v1/dev/tasks?detail=1` (Code #1045 item 5), the plain list, another company's caller, and a plain (non-workflow) task's detailed row. */
  list: { taskId: string; detailed: Answer; plain: Answer; omarDetailed: Answer; workflowTaskId: string; workflowDetailed: Answer };
  /** `GET /v1/dev/client/projects/{p}/members` refusals (Code #1022 CLIENT_MEMBERS_NOT_ALLOWED). */
  members: { memberRefused: Answer; otherCompanyProject: Answer; missingProject: Answer; ownerList: Answer };
}

export const CORE_TASK_ROUTES = JSON.parse(readFileSync(new URL("./code-core-task-routes.json", import.meta.url), "utf8")) as CoreTaskRoutesFixture;

/** A copy of a fixture value with Code's ids replaced (a test's own task id, for one). */
export function renamed<T>(value: T, replace: ReadonlyArray<readonly [string, string]>): T {
  let text = JSON.stringify(value);
  for (const [from, to] of replace) text = text.replaceAll(from, to);
  return JSON.parse(text) as T;
}
